from __future__ import annotations
import contextlib
import io
import json
import sys
from types import ModuleType

SOURCE = '#!/usr/bin/env python3\n"""退化图像文字还原的两个确定性体检：\n\n  mode=resolution  字符可识别性检出限（LOD）体检\n                   给字高/笔画宽（或直接给图，自动测量），判定该区域能否被识别。\n  mode=consensus   多通道读数一致性表决\n                   给同一单元的多次独立读数，输出共识与置信等级。\n\n纪律：不做识别、不做补字，只做"该不该采信"的判定。\n只用标准库；mode=resolution 若给 --image 需要 cv2（缺则要求手工给 --char-px）。\n\n示例：\n  python text_detectability.py --mode resolution --char-px 14 --stroke-px 1.2\n  python text_detectability.py --mode resolution --image page.png --lang cn\n  python text_detectability.py --mode consensus --reading 张强 --reading 高强敏 --reading 张强\n"""\nimport argparse\nimport difflib\nimport json\nimport sys\nfrom collections import Counter\n\n# 经验阈值（筛查用；最终判据仍是多通道一致 + 人工核验）\n# 中文：字高下限取 24px（常规 OCR 训练/输入区间），32px 以上稳定\nTH_CN = {"opt": 32.0, "ok": 24.0, "warn": 16.0}\nTH_EN = {"opt": 20.0, "ok": 12.0, "warn": 8.0}\nSTROKE = {"opt": 3.0, "ok": 2.0, "warn": 1.5}\nLOD_PX = {"cn": 24.0, "en": 12.0}\n\n\ndef grade_axis(value, th):\n    if value >= th["opt"]:\n        return "opt"\n    if value >= th["ok"]:\n        return "ok"\n    if value >= th["warn"]:\n        return "warn"\n    return "error"\n\n\ndef rank(g):\n    return {"opt": 0, "ok": 1, "warn": 2, "error": 3}[g]\n\n\ndef worst(grades):\n    return max(grades, key=rank)\n\n\ndef measure_image(path):\n    """用 cv2 从图像估计字高与笔画宽（中位数字符连通域）。失败返回 (None, msg)。"""\n    try:\n        import cv2  # type: ignore\n        import numpy as np  # type: ignore\n    except Exception as e:  # noqa: BLE001\n        return None, f"未安装 cv2/numpy（{e}），请手工用 --char-px/--stroke-px 给值"\n    img = cv2.imread(path, cv2.IMREAD_GRAYSCALE)\n    if img is None:\n        return None, f"图像读取失败：{path}"\n    # Otsu 反二值：文字=255\n    _, bw = cv2.threshold(img, 0, 255, cv2.THRESH_BINARY_INV + cv2.THRESH_OTSU)\n    n, labels, stats, _ = cv2.connectedComponentsWithStats(bw, connectivity=8)\n    heights, strokes = [], []\n    for i in range(1, n):\n        x, y, w, h, area = stats[i]\n        if h < 4 or h > 400 or w < 2 or w > 400:\n            continue\n        if area < 0.15 * w * h:  # 过于稀疏（噪点/边框）\n            continue\n        heights.append(h)\n        # 笔画宽：连通域内切圆直径 ≈ 2 * 最大距离变换值\n        mask = (labels[y:y + h, x:x + w] == i).astype(np.uint8)\n        dt = cv2.distanceTransform(mask, cv2.DIST_L2, 5)\n        if dt.max() > 0:\n            strokes.append(float(2.0 * dt.max()))\n    if not heights:\n        return None, "未找到有效字符连通域（图太糊/太干净/方向不对）"\n    h_med = float(np.median(heights))\n    w_med = float(np.median(strokes)) if strokes else None\n    return {"char_px": round(h_med, 1),\n            "stroke_px": round(w_med, 2) if w_med else None,\n            "n_components": len(heights)}, None\n\n\ndef mode_resolution(args):\n    out = {"status": "error", "mode": "resolution"}\n    lang = args.lang\n    char_px = args.char_px\n    stroke_px = args.stroke_px\n    measured = None\n    if char_px is None:\n        if not args.image:\n            out["error"] = "请给 --char-px（字高像素）或 --image（自动测量）"\n            return out, 1\n        measured, msg = measure_image(args.image)\n        if measured is None:\n            out["error"] = msg\n            return out, 1\n        char_px = measured["char_px"]\n        if stroke_px is None:\n            stroke_px = measured["stroke_px"]\n        out["measured_from_image"] = measured\n        out["image"] = args.image\n\n    th = TH_CN if lang == "cn" else TH_EN\n    lod = LOD_PX[lang]\n    g_h = grade_axis(char_px, th)\n    out.update({\n        "lang": lang,\n        "char_px": char_px,\n        "stroke_px": stroke_px,\n        "thresholds_px": th,\n        "lod_px": lod,\n        "conventions": {\n            "char_px": "字符高度（像素）——本领域的『采样率』口径",\n            "stroke_px": "笔画宽度（像素）——<1.5 单像素笔画在有损压缩下必然丢失",\n            "thresholds": "经验筛查阈值，来自常规 OCR 输入区间与工程经验；最终判据是多通道一致",\n        },\n    })\n\n    findings = []\n    grades = [g_h]\n    if "error" == g_h:\n        findings.append({"level": "error", "issue": "below_lod",\n                         "detail": f"字高 {char_px:g} px < 识别下限 {lod:g} px，该区域判定为『低于检出限』",\n                         "action": "报『< LOD』，不得输出具体字符；若必须给内容，只能作为推测并标红。"\n                                   "注意：<LOD 只说明单次识别不可靠，不代表不可反演——若退化为确定性且参数已知"\n                                   "（像素化、已知字体渲染），仍可尝试码本反演/去卷积（见 document-metrology.md §3）"})\n    elif g_h == "warn":\n        findings.append({"level": "warn", "issue": "near_lod",\n                         "detail": f"字高 {char_px:g} px 处于勉强区间（{th[\'warn\']:g}~{th[\'ok\']:g} px）",\n                         "action": "必须多通道表决，单次识别结果不可信；未知项标橙/红"})\n    else:\n        findings.append({"level": "ok", "issue": "resolution_ok",\n                         "detail": f"字高 {char_px:g} px 达到 {g_h} 档"})\n\n    if stroke_px is not None:\n        g_s = grade_axis(stroke_px, STROKE)\n        grades.append(g_s)\n        if g_s == "error":\n            findings.append({"level": "error", "issue": "stroke_too_thin",\n                             "detail": f"笔画宽 {stroke_px:g} px < 1.5 px，横竖笔画必然丢失/粘连",\n                             "action": "形近字（日曰、己已、未末）不可辨，按 <LOD 处理"})\n        elif g_s == "warn":\n            findings.append({"level": "warn", "issue": "stroke_thin",\n                             "detail": f"笔画宽 {stroke_px:g} px 偏细，易受压缩/模糊影响",\n                             "action": "提高扫描/拍摄分辨率重采；不可复现时按低置信处理"})\n\n    verdict = worst(grades)\n    out["grade"] = verdict\n    out["verdict"] = "error" if verdict == "error" else ("warn" if verdict == "warn" else "ok")\n    out["findings"] = findings\n    out["status"] = "ok"\n    if out["verdict"] == "error":\n        out["message"] = "低于检出限：该区域不能输出具体字符，只能标为推测或留占位"\n    elif out["verdict"] == "warn":\n        out["message"] = "接近检出限：结论必须基于多通道一致性，并逐字给置信等级"\n    else:\n        out["message"] = "分辨率满足识别要求"\n    return out, (2 if out["verdict"] == "error" else 0)\n\n\ndef _norm(s):\n    return "".join(ch for ch in s if not ch.isspace())\n\n\ndef mode_consensus(args):\n    out = {"status": "error", "mode": "consensus"}\n    readings = [r for r in (args.reading or []) if _norm(r) != ""]\n    if len(readings) < 2:\n        out["error"] = "至少给 2 个独立读数（--reading 可重复），才谈得上一致性"\n        return out, 1\n    norm = [_norm(r) for r in readings]\n    cnt = Counter(norm)\n    top, top_n = cnt.most_common(1)[0]\n    min_agree = max(2, args.min_agree)\n    n_total = len(norm)\n\n    # 近似一致：与最高票读数相似度 >= 阈值的也算支持\n    sim = args.sim\n    support = 0\n    for s in norm:\n        if s == top or difflib.SequenceMatcher(None, s, top).ratio() >= sim:\n            support += 1\n    ratio = support / n_total\n\n    if args.repeatability:\n        # 重复性审计：同一通道反复跑。只要出现任何分歧 → 该工具在此字段不可信。\n        mode_note = "repeatability（同一通道重复跑，测工具重复性）"\n        if top_n == n_total:\n            grade, verdict = "high", "ok"\n        else:\n            grade, verdict = "low", "error"\n        consensus = top if grade == "high" else None\n    else:\n        # 多通道一致性：不同独立预处理各跑一次，多数一致即有据。\n        mode_note = "multi-channel（不同独立通道，测一致性）"\n        if top_n >= min_agree and (top_n / n_total) >= 0.75:\n            grade, verdict = "high", "ok"\n            consensus = top\n        elif support >= min_agree:\n            grade, verdict = "medium", "warn"\n            consensus = top\n        else:\n            grade, verdict = "low", "error"\n            consensus = None\n\n    out.update({\n        "n_readings": n_total,\n        "readings": readings,\n        "vote_counts": dict(cnt),\n        "exact_top": top,\n        "exact_top_count": top_n,\n        "approx_support": support,\n        "agreement_ratio": round(ratio, 3),\n        "sim_threshold": sim,\n        "mode_note": mode_note,\n        "consensus": consensus,\n        "grade": grade,\n        "verdict": verdict,\n        "conventions": {\n            "grade": "high=强多数一致（≥75% 且≥min_agree）；medium=近似/弱多数；low=矛盾/孤证",\n            "rule": "多通道：≥2 独立通道相同/近似 → 有据；重复性：任何分歧 → 工具在此字段不可信",\n        },\n    })\n    if verdict == "ok":\n        out["message"] = f"{mode_note}：{top_n}/{n_total} 完全一致 → 高置信（黑）"\n    elif verdict == "warn":\n        out["message"] = f"{mode_note}：近似一致（支持 {support}/{n_total}）→ 中置信（橙），需标注"\n    elif args.repeatability:\n        out["message"] = f"{mode_note}：出现分歧 → 该通道在此字段不可信（弃用其输出作为证据）"\n    else:\n        out["message"] = f"{mode_note}：通道间矛盾或无多数 → 低置信（红），不得采信"\n    out["status"] = "ok"\n    return out, (0 if verdict != "error" else 2)\n\n\ndef main():\n    p = argparse.ArgumentParser(description="退化图像文字的检出限与一致性体检")\n    p.add_argument("--mode", default="resolution", choices=["resolution", "consensus"])\n    # resolution\n    p.add_argument("--char-px", type=float, default=None, help="字符高度（像素）")\n    p.add_argument("--stroke-px", type=float, default=None, help="笔画宽度（像素）")\n    p.add_argument("--lang", default="cn", choices=["cn", "en"])\n    p.add_argument("--image", default=None, help="图像路径（需要 cv2 自动测量）")\n    # consensus\n    p.add_argument("--reading", action="append", default=[], help="同一单元的独立读数，可重复")\n    p.add_argument("--min-agree", type=int, default=2, help="判定高置信所需的最少一致通道数")\n    p.add_argument("--sim", type=float, default=0.8, help="近似一致的相似度阈值")\n    p.add_argument("--repeatability", action="store_true",\n                   help="重复性审计模式：同一通道反复跑，任何分歧即判该工具在此字段不可信")\n    args = p.parse_args()\n\n    if args.mode == "resolution":\n        out, code = mode_resolution(args)\n    else:\n        out, code = mode_consensus(args)\n    print(json.dumps(out, ensure_ascii=False, indent=2))\n    return code\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n'

def main():
    capture, errors = io.StringIO(), io.StringIO()
    code = 0
    try:
        request = json.load(sys.stdin)
        args = request.get('args')
        if not isinstance(args, list) or any(not isinstance(x, str) for x in args):
            raise ValueError('args_must_be_string_list')
        sys.argv = ['text_detectability.py'] + args
        module = ModuleType('__main__')
        module.__file__ = 'text_detectability.py'
        sys.modules['__main__'] = module
        with contextlib.redirect_stdout(capture), contextlib.redirect_stderr(errors):
            exec(compile(SOURCE, 'text_detectability.py', 'exec'), module.__dict__)
    except SystemExit as error:
        code = error.code if isinstance(error.code, int) else 1
    except Exception as error:
        code = 1
        errors.write(type(error).__name__ + ': ' + str(error))
    print(json.dumps({'exit_code': code, 'stdout': capture.getvalue(), 'stderr': errors.getvalue()}, ensure_ascii=False))
    return code

if __name__ == '__main__':
    raise SystemExit(main())
